/**
 * Smart zoom model. Times are source-recording ms (so cuts don't move zooms);
 * points are normalised (0..1) to the full source frame.
 */

export const ZOOM_LEVELS = [1.25, 1.5, 2, 2.5, 3] as const;

export interface ZoomSegment {
  id: string;
  /** Zoom-in begins at `start`; fully zoomed at start + transition. */
  start: number;
  /** Zoom-out begins at `end`; back to 1× at end + transition. */
  end: number;
  level: number;
  /** follow = track the cursor (needs telemetry); fixed = stay on (x, y). */
  mode: "follow" | "fixed";
  x: number;
  y: number;
  /** Generated by auto zoom (replaced when auto settings change). */
  auto: boolean;
  /** Stable key of the interaction cluster an auto segment came from. */
  key?: string;
}

export interface ZoomSettings {
  /** Automatic zoom from cursor telemetry. */
  auto: boolean;
  /** Level used for automatic zooms and new manual zooms. */
  level: number;
  /** Duration of zoom in / out transitions (ms). */
  transitionMs: number;
  /** How long to stay zoomed after the last interaction (ms). */
  holdMs: number;
  /** 0..1, how gently the camera follows the cursor. */
  followSmoothing: number;
  /** Also zoom when the cursor pauses after moving (not just on clicks). */
  onPauses: boolean;
  segments: ZoomSegment[];
  /** Keys of auto zooms the user deleted (so regenerating doesn't bring them back). */
  dismissed: string[];
}

export const DEFAULT_ZOOM: ZoomSettings = {
  auto: false,
  level: 2,
  transitionMs: 700,
  holdMs: 1500,
  followSmoothing: 0.7,
  onPauses: false,
  segments: [],
  dismissed: [],
};

/** Camera for one frame: zoom `scale` centred on (cx, cy) in normalised source coords. */
export interface ZoomCamera {
  scale: number;
  cx: number;
  cy: number;
}
